/* Skipper Prep — topic 5: Sea marks, lights and sector lights.
   Facts: scratchpad/facts/buoyage-and-marks.md (verified 2026-10-03 against IALA R1001 Ed. 2.0, the Norwegian
   Coastal Administration guideline and List of Lights, the Norwegian pilot guide vol. 1, INT1 2013, Lovdata
   FOR-2012-12-19-1329 and the Norwegian Maritime Authority curriculum). Fact ids (F1...F106), scenarios (S-n),
   illustration specs (IL-n) and traps in comments refer to that sheet. Nothing below goes beyond it.
   Curriculum: part 3a (navigating by lighthouses, minor lights, fixed and floating marks; the IALA A system) and
   part 4 items 1.4.1 (pole/beacon with pointer, cardinal and lateral systems, special marks) and 1.4.2 (sectors and
   characteristics of minor lights). Chart symbols for rocks, cables and bridges are taught in the charts topic. */
(function () {
  'use strict';
  const S = BOAT.svg, C = S.COLORS, T = S.text;
  const INK = 'var(--ink)', INK2 = 'var(--ink-2)', MUTED = 'var(--muted)', LINE = 'var(--line)';
  const PAPER = 'var(--paper)', PAPER2 = 'var(--paper-2)', SHALLOW = 'var(--shallow)';
  const R = C.red, G = C.green, Y = C.yellow, B = C.black, W = C.white, BU = C.blue;
  const fx = n => Math.round(n * 100) / 100;
  let uid = 0;

  /* ---------- unlabelled marks for picture questions and lesson rows ----------
     Colours top to bottom, shapes, topmarks and lights: IALA R1001 Tables 1, 5-9, 11 (F10, F11, F23-F26, F33, F36,
     F40, F45). Norwegian spar tops: red blunt, green pointed (F14); black-topped cardinals pointed, yellow-topped
     blunt (F30). Reflective bands (blue stands for black): F16, F31, F35, F39, F41. */
  const QK = {
    'lateral-port':      { bands: [[R, 1]], shape: 'can', top: 'can', tc: R, light: R, spar: 'blunt', reflex: [R] },
    'lateral-starboard': { bands: [[G, 1]], shape: 'cone', top: 'cone-up', tc: G, light: G, spar: 'pointed', reflex: [G] },
    'cardinal-n':        { bands: [[B, .5], [Y, .5]], shape: 'pillar', top: 'cones-up', tc: B, light: W, spar: 'pointed', reflex: [BU, Y] },
    'cardinal-e':        { bands: [[B, .3], [Y, .4], [B, .3]], shape: 'pillar', top: 'cones-base', tc: B, light: W, spar: 'pointed', reflex: [BU, BU] },
    'cardinal-s':        { bands: [[Y, .5], [B, .5]], shape: 'pillar', top: 'cones-down', tc: B, light: W, spar: 'blunt', reflex: [Y, BU] },
    'cardinal-w':        { bands: [[Y, .33], [B, .34], [Y, .33]], shape: 'pillar', top: 'cones-point', tc: B, light: W, spar: 'blunt', reflex: [Y, Y] },
    'isolated-danger':   { bands: [[B, .3], [R, .4], [B, .3]], shape: 'pillar', top: 'two-balls', tc: B, light: W, spar: null, reflex: [BU, R] },
    'safe-water':        { bands: [[R, 1], [W, 1], [R, 1], [W, 1], [R, 1], [W, 1]], vertical: true, shape: 'sphere', top: 'ball', tc: R, light: W, spar: null, reflex: [R, W] },
    'special':           { bands: [[Y, 1]], shape: 'pillar', top: 'x', tc: Y, light: Y, spar: null, reflex: [Y] },
    'wreck':             { bands: [[BU, 1], [Y, 1], [BU, 1], [Y, 1], [BU, 1], [Y, 1]], vertical: true, shape: 'pillar', top: 'plus', tc: Y, light: [BU, Y], spar: null, reflex: [] },
  };
  const O = `stroke="${INK}" stroke-width="1" stroke-linejoin="round"`;
  function cone(cx, yBase, w, h, up, fill) {
    const p = up ? `${fx(cx - w / 2)},${yBase} ${fx(cx + w / 2)},${yBase} ${cx},${yBase - h}` : `${fx(cx - w / 2)},${yBase - h} ${fx(cx + w / 2)},${yBase - h} ${cx},${yBase}`;
    return `<polygon points="${p}" fill="${fill}" ${O}/>`;
  }
  function topmark(k, cx, yb) {
    const c = k.tc, ball = cy => `<circle cx="${cx}" cy="${cy}" r="14" fill="${c}" ${O}/>`;
    switch (k.top) {
      case 'can': return { svg: `<rect x="${cx - 17}" y="${yb - 30}" width="34" height="30" fill="${c}" ${O}/>`, h: 30 };
      case 'cone-up': return { svg: cone(cx, yb, 38, 34, true, c), h: 34 };
      case 'cones-up': return { svg: cone(cx, yb, 36, 26, true, c) + cone(cx, yb - 32, 36, 26, true, c), h: 58 };          // N: both point up
      case 'cones-down': return { svg: cone(cx, yb, 36, 26, false, c) + cone(cx, yb - 32, 36, 26, false, c), h: 58 };      // S: both point down
      case 'cones-base': return { svg: cone(cx, yb, 36, 26, false, c) + cone(cx, yb - 30, 36, 26, true, c), h: 56 };       // E: base to base (points outward)
      case 'cones-point': return { svg: cone(cx, yb, 36, 26, true, c) + cone(cx, yb - 30, 36, 26, false, c), h: 56 };      // W: point to point (hourglass)
      case 'two-balls': return { svg: ball(yb - 14) + ball(yb - 46), h: 60 };
      case 'ball': return { svg: `<circle cx="${cx}" cy="${yb - 16}" r="16" fill="${c}" ${O}/>`, h: 32 };
      case 'x': return { svg: `<g stroke="${c}" stroke-width="9" stroke-linecap="round"><line x1="${cx - 17}" y1="${yb - 36}" x2="${cx + 17}" y2="${yb - 2}"/><line x1="${cx + 17}" y1="${yb - 36}" x2="${cx - 17}" y2="${yb - 2}"/></g>`, h: 38 };
      case 'plus': return { svg: `<g stroke="${c}" stroke-width="9" stroke-linecap="square"><line x1="${cx}" y1="${yb - 40}" x2="${cx}" y2="${yb - 2}"/><line x1="${cx - 18}" y1="${yb - 21}" x2="${cx + 18}" y2="${yb - 21}"/></g>`, h: 42 };
    }
    return { svg: '', h: 0 };
  }
  /* body + topmark + light in local coordinates: origin = centre of the waterline, y negative upwards */
  function body(kind, form, light) {
    const k = QK[kind], id = 'qm' + (uid++);
    let H, halfW, shape, hasTop = true, extra = '';
    form = form || k.shape;
    if (form === 'can') { H = 112; halfW = 46; shape = `<rect x="${-halfW}" y="${-H}" width="${2 * halfW}" height="${H}"/>`; }
    else if (form === 'cone') { H = 132; halfW = 50; shape = `<polygon points="${-halfW},0 ${halfW},0 ${halfW},-26 0,${-H} ${-halfW},-26"/>`; }
    else if (form === 'sphere') { H = 120; halfW = 60; shape = `<circle cx="0" cy="-60" r="60"/>`; }
    else if (form === 'spar') {
      hasTop = false; halfW = 12; H = 230;
      shape = k.spar === 'pointed' ? `<polygon points="${-halfW},0 ${halfW},0 ${halfW},${-(H - 26)} 0,${-H} ${-halfW},${-(H - 26)}"/>` : `<rect x="${-halfW}" y="${-H}" width="${2 * halfW}" height="${H}"/>`;
      k.reflex.forEach((c, i) => { extra += `<rect x="${-halfW - 1}" y="${-(H - 40) + i * 22}" width="${2 * halfW + 2}" height="12" fill="${c}" stroke="${W}" stroke-width="1.5"/>`; });
    }
    else { H = 150; halfW = 36; shape = `<polygon points="${-halfW},0 ${halfW},0 24,${-H} -24,${-H}"/>`; }
    let fill = `<defs><clipPath id="${id}">${shape}</clipPath></defs><g clip-path="url(#${id})">`;
    if (k.vertical) { const n = k.bands.length, w = 2 * halfW / n; k.bands.forEach((b, i) => { fill += `<rect x="${fx(-halfW + i * w)}" y="${-H - 2}" width="${fx(w + .5)}" height="${H + 4}" fill="${b[0]}"/>`; }); }
    else { let y = -H; k.bands.forEach(b => { const h = H * b[1]; fill += `<rect x="${-halfW - 2}" y="${fx(y)}" width="${2 * halfW + 4}" height="${fx(h + .5)}" fill="${b[0]}"/>`; y += h; }); }
    fill += '</g>' + shape.replace('/>', ` fill="none" stroke="${INK}" stroke-width="1.4" stroke-linejoin="round"/>`) + extra;
    let top = -H, svg = fill;
    if (hasTop) { const st = -H - 16; svg += `<line x1="0" y1="${-H}" x2="0" y2="${st}" stroke="${INK}" stroke-width="3"/>`; const tm = topmark(k, 0, st); svg += tm.svg; top = st - tm.h; }
    if (light) {
      const ly = top - 24;
      svg += `<line x1="0" y1="${top}" x2="0" y2="${ly}" stroke="${INK}" stroke-width="2"/><rect x="-13" y="${ly - 13}" width="26" height="26" rx="6" fill="${C.hullDark}"/>`;
      if (Array.isArray(k.light)) svg += `<path d="M0,${ly - 9} A9,9 0 0,0 0,${ly + 9} Z" fill="${k.light[0]}"/><path d="M0,${ly - 9} A9,9 0 0,1 0,${ly + 9} Z" fill="${k.light[1]}"/>`;
      else svg += `<circle cx="0" cy="${ly}" r="9" fill="${k.light}"/>`;
      top = ly - 22;
    }
    return { svg, top };
  }
  const water = (x, y, w, h) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${SHALLOW}"/><path d="M${x},${y} ${Array.from({ length: Math.ceil(w / 16) }, (_, i) => `q4,-4 8,0 t8,0`).join(' ')}" fill="none" stroke="${INK2}" stroke-width="1" opacity=".5"/>`;
  /* one unlabelled mark for a picture question */
  function qmark(kind, opts) {
    opts = opts || {};
    const Wd = 300, Ht = 360, wl = 290, cx = 150, m = body(kind, opts.form, opts.light);
    const sc = Math.min(1, 262 / (-m.top + 8));
    let inner = `<rect width="${Wd}" height="${Ht}" fill="${PAPER}" rx="8"/>` + water(0, wl, Wd, Ht - wl);
    inner += `<g transform="translate(${cx},${wl}) scale(${fx(sc)})">${m.svg}</g>`;
    inner += T(cx, Ht - 14, opts.note || 'What is this mark?', { size: 12, fill: MUTED });
    return S.svg(Wd, Ht, inner, { label: opts.label || 'A sea mark shown for identification' });
  }
  /* a row of labelled marks for the lesson */
  function markRow(title, items, opts) {
    opts = opts || {};
    const Wd = 640, wl = 250, cw = Wd / items.length, maxL = Math.max(...items.map(it => it.label.length)), Ht = wl + 62 + maxL * 15 + 28, fs = items.length > 5 ? 10.5 : 11;
    let inner = `<rect width="${Wd}" height="${Ht}" fill="${PAPER}" rx="8"/>` + T(Wd / 2, 22, title, { size: 15, weight: 700 }) + water(0, wl, Wd, 44);
    items.forEach((it, i) => {
      const x = cw * (i + .5), m = body(it.kind, it.form, it.light), sc = Math.min(.62, 200 / (-m.top + 8));
      inner += `<g transform="translate(${fx(x)},${wl}) scale(${fx(sc)})">${m.svg}</g>`;
      it.label.forEach((l, j) => { inner += T(x, wl + 62 + j * 15, l, { size: j === 0 ? 12 : fs, weight: j === 0 ? 700 : 500, fill: j === 0 ? INK : INK2 }); });
    });
    if (opts.footer) inner += T(Wd / 2, Ht - 12, opts.footer, { size: 11, fill: MUTED });
    return S.svg(Wd, Ht, inner, { label: opts.label || title });
  }
  function familyRow() {
    return markRow('The IALA mark family (Region A, as used in Norway)', [
      { kind: 'lateral-port', light: true, label: ['Port lateral', 'red can', 'red light'] },
      { kind: 'lateral-starboard', light: true, label: ['Starboard lateral', 'green cone', 'green light'] },
      { kind: 'cardinal-n', light: true, label: ['Cardinal (north)', 'black and yellow', 'white light'] },
      { kind: 'isolated-danger', light: true, label: ['Isolated danger', 'black, red band', 'white Fl(2)'] },
      { kind: 'safe-water', light: true, label: ['Safe water', 'red/white stripes', 'white light'] },
      { kind: 'special', light: true, label: ['Special', 'yellow', 'yellow light'] },
    ], { footer: 'By day: colour, shape and topmark. By night: colour and rhythm of the light (F3).', label: 'Six marks side by side: red can port lateral with red light, green cone starboard lateral with green light, black-over-yellow north cardinal with two cones up and white light, black pillar with red band and two black balls (isolated danger), red and white vertically striped sphere with red ball (safe water), yellow pillar with yellow X (special).' });
  }
  function lateralRow() {
    return markRow('Lateral marks: IALA buoys and the Norwegian spar and perch forms', [
      { kind: 'lateral-port', form: 'can', label: ['Port: red CAN', 'red can topmark'] },
      { kind: 'lateral-starboard', form: 'cone', label: ['Starboard: green CONE', 'green cone topmark'] },
      { kind: 'lateral-port', form: 'spar', label: ['Norwegian red spar', 'BLUNT top, red band'] },
      { kind: 'lateral-starboard', form: 'spar', label: ['Norwegian green spar', 'POINTED top, green band'] },
    ], { footer: 'Keep red to port and green to starboard when travelling in the direction of buoyage (F12).', label: 'Four lateral marks: red can buoy with red can topmark, green conical buoy with green cone topmark, red Norwegian spar buoy with a blunt top and one red reflective band, green Norwegian spar buoy with a pointed top and one green reflective band.' });
  }
  function dangerRow() {
    return markRow('Isolated danger, safe water, special and emergency wreck marks', [
      { kind: 'isolated-danger', light: true, label: ['Isolated danger', 'black, red band, 2 black balls', 'Fl(2) W'] },
      { kind: 'safe-water', light: true, label: ['Safe water', 'red/white VERTICAL, red ball', 'Iso, Oc, LFl 10s or Mo(A) W'] },
      { kind: 'special', light: true, label: ['Special mark', 'yellow, yellow X', 'yellow light, e.g. Fl(4) Y'] },
      { kind: 'wreck', light: true, label: ['Emergency wreck', 'blue/yellow VERTICAL, yellow +', 'Al Bu/Y 1 s each'] },
    ], { footer: 'Horizontal bands = danger-type marks; vertical stripes = safe water or a new wreck (trap 4).', label: 'Four marks: black pillar with a broad red band and two black spheres (isolated danger, white Fl(2) light); red and white vertically striped sphere with a red ball (safe water); yellow pillar with a yellow X (special, yellow light); blue and yellow vertically striped pillar with an upright yellow cross (emergency wreck, alternating blue and yellow light).' });
  }
  /* IL-6: the four cardinal light rhythms on 15-second timelines (IALA Tables 5-6, F23-F26, F28) */
  function cardinalRhythms() {
    const Wd = 640, Ht = 318, x0 = 150, x1 = 600, sx = (x1 - x0) / 15, rows = [
      ['NORTH', 'Q (continuous)', '12 o\'clock', Array.from({ length: 15 }, (_, i) => [i, i + .5])],
      ['EAST', 'Q(3) 10s', '3 o\'clock', [[0, .5], [1, 1.5], [2, 2.5], [10, 10.5], [11, 11.5], [12, 12.5]]],
      ['SOUTH', 'Q(6)+LFl 15s', '6 o\'clock', [[0, .5], [1, 1.5], [2, 2.5], [3, 3.5], [4, 4.5], [5, 5.5], [7, 9]]],
      ['WEST', 'Q(9) 15s', '9 o\'clock', Array.from({ length: 9 }, (_, i) => [i, i + .5])],
    ];
    let inner = `<rect width="${Wd}" height="${Ht}" fill="${PAPER}" rx="8"/>` + T(Wd / 2, 22, 'Cardinal lights: count the white flashes like a clock face', { size: 15, weight: 700 });
    rows.forEach((r, i) => {
      const by = 52 + i * 60;
      inner += T(12, by + 10, r[0], { size: 13, weight: 800, anchor: 'start' }) + T(12, by + 27, r[1], { size: 11.5, anchor: 'start', fill: INK2 }) + T(12, by + 41, r[2], { size: 11, anchor: 'start', fill: MUTED });
      inner += `<rect x="${x0}" y="${by}" width="${x1 - x0}" height="34" fill="${C.night}" rx="3"/>`;
      r[3].forEach(iv => { inner += `<rect x="${fx(x0 + iv[0] * sx)}" y="${by + 3}" width="${fx((iv[1] - iv[0]) * sx)}" height="28" fill="${W}" rx="2"/>`; });
      if (i === 1) inner += `<line x1="${fx(x0 + 10 * sx)}" y1="${by - 4}" x2="${fx(x0 + 10 * sx)}" y2="${by + 38}" stroke="${INK2}" stroke-width="1" stroke-dasharray="3 3"/>` + T(x0 + 10 * sx + 4, by - 8, 'period 10 s: group repeats', { size: 10, anchor: 'start', fill: INK2 });
      if (i === 2) inner += T(x0 + 8 * sx, by + 46, 'long flash (2 s or more)', { size: 10, fill: INK2 });
      for (let t = 0; t <= 15; t++) inner += `<line x1="${fx(x0 + t * sx)}" y1="${by + 34}" x2="${fx(x0 + t * sx)}" y2="${by + 38}" stroke="${INK2}" stroke-width="1"/>`;
    });
    for (let t = 0; t <= 15; t += 5) inner += T(x0 + t * sx, 300, t + ' s', { size: 11, fill: INK2 });
    inner += T(Wd / 2, Ht - 6, 'Q = 50 or 60 flashes a minute; VQ = 100 or 120 a minute with periods 5 s / 10 s / 10 s (F29).', { size: 10.5, fill: MUTED });
    return S.svg(Wd, Ht, inner, { label: 'Four timelines of white flashes: north continuous quick flashes; east three flashes every 10 seconds; south six flashes followed by one long flash every 15 seconds; west nine flashes every 15 seconds.' });
  }
  /* plan-view boat, bow up */
  function boat(x, y, L) {
    L = L || 40; const Wb = L * .38;
    return `<polygon points="${x},${fx(y - L / 2)} ${fx(x + Wb / 2)},${fx(y - L / 8)} ${fx(x + Wb / 2)},${fx(y + L / 2)} ${fx(x - Wb / 2)},${fx(y + L / 2)} ${fx(x - Wb / 2)},${fx(y - L / 8)}" fill="${INK2}" stroke="${PAPER}" stroke-width="1"/>` +
      `<line x1="${x}" y1="${fx(y - L / 2 - 4)}" x2="${x}" y2="${fx(y - L / 2 - 18)}" stroke="${INK}" stroke-width="2"/><polygon points="${x},${fx(y - L / 2 - 22)} ${x - 4},${fx(y - L / 2 - 14)} ${x + 4},${fx(y - L / 2 - 14)}" fill="${INK}"/>`;
  }
  const rock = (x, y, r) => `<path d="M${x - r},${y} q${r * .3},${-r * 1.1} ${r},${-r * .8} q${r * .9},${.3 * r} ${r},${r * .8} q${-r * .3},${r * .9} ${-r},${r * .8} q${-r * .9},${-.1 * r} ${-r},${-r * .8} Z" fill="${MUTED}" opacity=".8"/>`;
  /* IL-13 as a quiz picture: boat heading TOWARDS the light; red lies to port of the white sector, green to starboard (F64).
     Angles are measured from the light (0 = up): green 120-170, white 170-190, red 190-240; the boat sits at `where`. */
  function sectorScene(where) {
    const Wd = 480, Ht = 420, lx = 240, ly = 86, RAD = 360;
    let inner = `<rect width="${Wd}" height="${Ht}" fill="${SHALLOW}" rx="8"/>`;
    [[120, 170, G, .32], [170, 190, Y, .3], [190, 240, R, .32]].forEach(([a, b, c, o]) => { inner += S.sector(lx, ly, RAD, a, b, c, o); });
    inner += rock(118, 260, 22) + rock(362, 260, 22);
    inner += `<path d="M0,0 H${Wd} V60 Q400,70 330,62 Q270,54 240,96 Q210,54 150,62 Q80,70 0,60 Z" fill="${PAPER2}" stroke="${LINE}" stroke-width="1.2"/>`;
    inner += `<rect x="${lx - 13}" y="${ly - 6}" width="26" height="24" fill="${W}" stroke="${INK}" stroke-width="1.2"/><polygon points="${lx - 16},${ly - 6} ${lx + 16},${ly - 6} ${lx},${ly - 22}" fill="${R}" stroke="${INK}" stroke-width="1.2"/>`;
    inner += T(lx, 40, 'sector light', { size: 12, weight: 700 });
    const pos = { white: [180, 280], green: [150, 265], red: [212, 265] }[where] || [180, 280];
    const bx = lx + pos[1] * Math.sin(S.deg(pos[0])), by = ly - pos[1] * Math.cos(S.deg(pos[0]));
    inner += boat(fx(bx), fx(by), 44);
    inner += T(Wd / 2, Ht - 12, 'The boat is heading towards the light. Which colour does it see?', { size: 12, fill: INK2 });
    return S.svg(Wd, Ht, inner, { label: `Plan view of a sector light on a headland with a green sector on the right, a white sector in the middle and a red sector on the left as seen by a boat heading towards the light; the boat is in the ${where} sector.` });
  }
  /* unlabelled pole with a pointer arm for a picture question (F50) */
  function qpole(dir) {
    const Wd = 360, Ht = 300, wl = 220, cx = 180;
    let inner = `<rect width="${Wd}" height="${Ht}" fill="${PAPER}" rx="8"/>` + water(0, wl, Wd, Ht - wl) + rock(cx, wl + 4, 44);
    inner += `<line x1="${cx}" y1="${wl}" x2="${cx}" y2="70" stroke="${INK}" stroke-width="6" stroke-linecap="round"/>`;
    const x2 = cx + dir * 70;
    inner += `<line x1="${cx}" y1="90" x2="${x2}" y2="90" stroke="${INK}" stroke-width="6" stroke-linecap="round"/><circle cx="${cx}" cy="64" r="7" fill="${INK}"/>`;
    inner += T(cx, Ht - 14, 'An iron pole on a rock with a pointer arm', { size: 12, fill: MUTED });
    return S.svg(Wd, Ht, inner, { label: `Iron pole standing on a rock with a horizontal arm pointing to the ${dir < 0 ? 'left' : 'right'}` });
  }
  /* unlabelled leading-mark window (IL-17): front mark lower with apex up, rear mark higher with apex down, offset sideways */
  function qlead(offset) {
    const Wd = 320, Ht = 250, hz = 176, cx = 160;
    let inner = `<rect width="${Wd}" height="${Ht}" fill="${PAPER}" rx="8"/>`;
    inner += `<path d="M4,${hz} Q90,${hz - 30} 170,${hz - 20} Q250,${hz - 10} ${Wd - 4},${hz - 22} V${hz} Z" fill="${PAPER2}"/>` + `<rect x="4" y="${hz}" width="${Wd - 8}" height="${Ht - hz - 30}" fill="${SHALLOW}"/>`;
    const rx = cx + offset;
    inner += `<line x1="${rx}" y1="${hz - 10}" x2="${rx}" y2="${hz - 96}" stroke="${INK}" stroke-width="2"/>` + cone(rx, hz - 64, 28, 30, false, R);
    inner += `<line x1="${cx}" y1="${hz + 8}" x2="${cx}" y2="${hz - 44}" stroke="${INK}" stroke-width="2.5"/>` + cone(cx, hz - 14, 32, 32, true, R);
    inner += T(cx, Ht - 12, 'Two leading marks seen from your boat', { size: 12, fill: MUTED });
    return S.svg(Wd, Ht, inner, { label: `Two leading marks: the rear, higher mark (apex down) appears ${offset === 0 ? 'exactly above' : offset > 0 ? 'to the right of' : 'to the left of'} the front, lower mark (apex up).` });
  }

  BOAT.register({
    id: 'buoyage-and-marks',
    title: 'Sea marks, lights and sector lights',
    order: 5,
    examShare: 6,
    examWeight: 'about 5–8 of 50 questions, many of them in part 4',
    summary: 'How Norway marks its waters and how you read the marks by day and by night: the direction of buoyage and the red and green lateral marks, the four black-and-yellow cardinal marks and their clock-face light rhythms, isolated danger, safe water, special and emergency wreck marks, the Norwegian spar buoys without topmarks, iron poles with pointer arms, light characters such as Fl, Oc, Iso and Q, how to decode a light description on the chart, sector lights (white = fairway, red to port and green to starboard when you head for the light), leading lines and bridge marking. This is curriculum part 3; the lateral and cardinal systems, special marks, pointer poles and the sectors and characters of minor lights are also part 4 items 1.4.1 and 1.4.2, where more than two wrong answers fail the whole exam.',
    sections: [
      // 1 ------------------------------------------------------------
      {
        id: 'intro',
        title: 'What sea marks are and how the exam tests them',
        html: `<p>A sea mark is a signpost on the water. Rocks, shoals and channels look the same from a boat, so the Norwegian Coastal Administration maintains about <strong>22,000 marks</strong> along the coast: roughly 12,000 fixed unlit marks, about 2,000 minor lights and around 100 working lighthouses. Every mark has a meaning that is fixed by an international system, the <strong>IALA Maritime Buoyage System</strong>, and Norway belongs to <strong>Region A</strong>. Regions A and B differ only in the colours of the lateral (channel-side) marks; every other mark is identical worldwide.</p>
<p>The system uses five mark types in combination: <strong>lateral</strong> marks show the sides of a channel, <strong>cardinal</strong> marks say on which compass side of a danger the safe water lies, <strong>isolated danger</strong> marks sit on a small danger with water all around, <strong>safe water</strong> marks show open water, and <strong>special</strong> marks show an area or feature described on the chart. A sixth, the emergency wreck marking buoy, is used for brand-new dangers. By day you identify a mark by its <strong>colour, shape and topmark</strong>; by night by the <strong>colour and rhythm of its light</strong>.</p>
<p>The exam tests this in two places. <strong>Part 3 (navigation and chart reading)</strong> asks you to navigate by lighthouses, minor lights and fixed and floating marks and to know the IALA A system. <strong>Part 4 (particularly important topics)</strong> item <strong>1.4.1</strong> covers the pole or beacon with a pointer arm, the cardinal and lateral systems and special marks, and item <strong>1.4.2</strong> covers the sectors and characteristics of minor lights. Part 4 has its own rule: more than two wrong answers there fail the whole exam, however well you do elsewhere. Expect pictures: a mark to identify and a side to pass on, a chart light description to decode, a sector light to interpret, a pole with a pointer.</p>
<div class="callout tip"><p>Three questions to ask of every mark: <strong>What is it?</strong> (colour, shape, topmark or light), <strong>What does it tell me?</strong> (which side is safe), <strong>Where is it on the chart?</strong> (the mark alone never shows how big the danger is).</p></div>`,
        illustration: () => familyRow(),
        caption: 'The IALA family as used in Norway: lateral port and starboard, cardinal (one of four), isolated danger, safe water and special. The emergency wreck buoy comes later.',
        keyFacts: ['Norway uses IALA Region A; A and B differ only in lateral (and preferred channel) marks', 'Five mark types: lateral, cardinal, isolated danger, safe water, special; plus the emergency wreck buoy', 'By day: colour, shape, topmark. By night: light colour and rhythm', 'Part 3 covers the whole topic; part 4 items 1.4.1 (marks, pointer poles) and 1.4.2 (sectors and light characters) allow at most 2 errors', 'The mark never shows the size of the danger: always check the chart'],
        check: { id: 'buoyage-c1', q: 'Which buoyage region does Norway belong to, and what does that change?', options: ['Region B: red marks are kept to starboard when entering from sea', 'Region A: red lateral marks are kept to port when entering from sea; all other marks are the same worldwide', 'Region A: cardinal marks are red and green', 'Region B: cardinal marks are not used in Norway'], answer: 1, explanation: 'Norway is in IALA Region A, where port-hand marks are red. Regions A and B differ only in the lateral and preferred-channel marks; cardinal, isolated danger, safe water and special marks are identical everywhere (F1).' },
      },
      // 2 ------------------------------------------------------------
      {
        id: 'direction',
        title: 'Direction of buoyage and the lateral marks',
        html: `<p>Lateral marks only make sense if everybody agrees which way is "forward". That reference is the <strong>direction of buoyage</strong>: the direction you travel when <strong>approaching a harbour, river, fjord or other waterway from seaward</strong>. Along the open coast, where there is no obvious "inwards", the authority fixes the direction, in principle <strong>clockwise around land masses</strong>. Around Norway that means from the Swedish border <strong>westwards along the south coast</strong>, then <strong>northwards up the west coast</strong> and on to the Russian border; into every fjord and harbour it runs from the sea inwards. Where the direction is not obvious the chart shows it with a <strong>magenta arrow</strong>.</p>
<p>Travelling in the direction of buoyage in Region A you keep <strong>red marks on your port (left) side</strong> and <strong>green marks on your starboard (right) side</strong>. The <strong>port-hand mark</strong> is red, <strong>can-shaped</strong> (flat top), with a single red can topmark if it has one, and a <strong>red light of any rhythm except Fl(2+1)</strong>. The <strong>starboard-hand mark</strong> is green, <strong>conical</strong> (pointed), with a single green cone point up as topmark, and a <strong>green light of any rhythm except Fl(2+1)</strong>. When you travel <strong>against</strong> the direction of buoyage, for example leaving harbour, the rule simply reverses: red is now on your starboard side and green on your port side.</p>
<p>If lateral marks are numbered, the numbers also follow the direction of buoyage: <strong>even numbers on red (port) marks, odd numbers on green (starboard) marks</strong>, counting up from seaward.</p>
<div class="callout warn"><p>"Red right returning" is the rule in Region B (the Americas, Japan, Korea, the Philippines). In Norway it is the opposite: <strong>red to port when returning from sea</strong>. If a question talks about the boat leaving harbour, swap the sides before you answer.</p></div>`,
        illustration: () => S.lateralChannel(),
        caption: 'Entering from seaward (bottom) you follow the magenta direction-of-buoyage arrow: red cans with even numbers on your left, green cones with odd numbers on your right. The boat leaving harbour sees the colours swapped.',
        keyFacts: ['Direction of buoyage = from seaward into harbours and fjords; along the coast clockwise round Norway (west along the south coast, north up the west coast); magenta arrow on the chart where unclear', 'Port-hand mark: red, can, red can topmark, red light (any rhythm except Fl(2+1)); keep it to PORT when going with the direction of buoyage', 'Starboard-hand mark: green, cone, green cone topmark, green light (any rhythm except Fl(2+1)); keep it to STARBOARD', 'Against the direction of buoyage (leaving) the sides swap: red to starboard, green to port', 'Numbers: even on red, odd on green'],
        check: { id: 'buoyage-c2', q: 'You are entering a harbour from the sea at dusk and see a red can buoy slightly to the left and a green conical buoy slightly to the right of your bow. What do you do?', options: ['Steer between them: red stays to port, green to starboard', 'Pass both buoys on your port side', 'Turn around: red and green together mean the harbour is closed', 'Steer left of the red buoy, because red marks the deep water'], answer: 0, explanation: 'Approaching from seaward is the direction of buoyage, so red is kept to port and green to starboard: the channel runs between them (S1, F6, F12).' },
      },
      // 3 ------------------------------------------------------------
      {
        id: 'lateral-norway',
        title: 'Lateral marks the Norwegian way: spars, perches, numbers',
        html: `<p>The IALA pictures show tidy cans and cones with topmarks. On the Norwegian coast most floating marks are <strong>spar buoys</strong>: tall thin poles, and <strong>topmarks are omitted on most of them</strong> because the weather destroys them. Topmarks are used on only a small fraction of marks and are <strong>not shown on the chart</strong>. Instead the spar tells you its meaning by <strong>colour and the shape of its top</strong>: a <strong>red spar has a blunt, flat top</strong>; a <strong>green spar has a pointed top</strong>. Think of the IALA shapes: the port can is flat on top, the starboard cone is pointed. Each floating lateral mark also carries one <strong>reflective band</strong> in its colour, red or green, so a torch or searchlight shows the colour at night.</p>
<p>Fixed lateral marks stand on the rock itself. In Norway these <strong>iron poles or perches</strong> are painted <strong>white with a red band</strong> (port) or <strong>white with a green band</strong> (starboard), or black without a band, with reflective tape or a figure in the same colour: a red band or square for port, a green band or triangle for starboard. On a fixed beacon only the <strong>shape of the topmark</strong> has navigational meaning; the shape of the pole does not.</p>
<p>Elsewhere in the world you may meet <strong>preferred channel marks</strong> at a junction: a red buoy with one broad green band (preferred channel to starboard, treated as a port mark, light Fl(2+1) R) or a green buoy with a broad red band (preferred channel to port, treated as a starboard mark, Fl(2+1) G). <strong>They are not used in Norwegian waters</strong>, but their rhythm explains the one rule you must remember: <strong>Fl(2+1)</strong> is the only rhythm an ordinary red or green lateral light may <em>not</em> show.</p>
<div class="callout tip"><p>Red = blunt = can. Green = pointed = cone. Even numbers red, odd numbers green. Light colour = mark colour.</p></div>`,
        illustration: () => lateralRow(),
        caption: 'IALA buoys with topmarks (left) and the Norwegian spar forms without them (right): red with a blunt top, green with a pointed top, each with one reflective band.',
        keyFacts: ['Most Norwegian buoys have NO topmark; topmarks are not charted', 'Red spar: blunt (flat) top; green spar: pointed top; one reflective band in the mark colour', 'Fixed lateral poles: white with a red band (port) or a green band (starboard); on a fixed beacon only the topmark shape has meaning', 'Preferred channel marks (banded red/green, light Fl(2+1)) are NOT used in Norway', 'An ordinary lateral light may have any rhythm EXCEPT Fl(2+1)'],
        check: { id: 'buoyage-c3', q: 'A tall red spar buoy with a flat top and no topmark lies ahead as you sail into a fjord from the sea. What is it and where do you pass?', options: ['A special mark; pass on either side', 'An isolated danger mark; keep well clear on either side', 'A starboard-hand lateral mark; keep it on your right', 'A port-hand lateral mark; keep it on your left'], answer: 3, explanation: 'In Norway red laterals are blunt-topped spars without a topmark. Going into the fjord is the direction of buoyage, so the red mark stays on your port side (F13, F14, F12).' },
      },
      // 4 ------------------------------------------------------------
      {
        id: 'cardinal',
        title: 'Cardinal marks: the name says where to pass',
        html: `<p>A cardinal mark answers one question: <strong>on which compass side of the danger is the safe water?</strong> Draw four quadrants around the danger, bounded by the true bearings <strong>NW–NE, NE–SE, SE–SW and SW–NW</strong> from the danger. A mark placed in the north quadrant is a <strong>north cardinal</strong> and you <strong>pass north of it</strong>; the danger lies to its south. The same for east, south and west. The name is the side to pass on, <em>not</em> where the danger is. Cardinal marks are used to show where the deepest water is, the safe side of a danger, a bend or junction, or the end of a shoal.</p>
<p>Cardinal marks have no special body shape (pillar or spar) but are always painted in <strong>black and yellow horizontal bands</strong> with <strong>two black cones</strong> as topmark. The cones point towards the black band:</p>
<ul>
<li><strong>North</strong>: black over yellow; both cones point <strong>up</strong>.</li>
<li><strong>East</strong>: black–yellow–black; cones <strong>base to base</strong> (points outward, like a diamond or an egg).</li>
<li><strong>South</strong>: yellow over black; both cones point <strong>down</strong>.</li>
<li><strong>West</strong>: yellow–black–yellow (black band about a third of the height); cones <strong>point to point</strong> (like a wineglass or hourglass).</li>
</ul>
<div class="callout tip"><p>Points up = black on top (N). Points down = black at the bottom (S). Points outward = black at top and bottom (E). Points inward = black in the middle (W). Candidates most often mix up east and west: east is the egg, west is the wineglass.</p></div>
<p>Two more things the exam likes: a cardinal mark's light is always <strong>white</strong>, and the mark never tells you how big the danger is, so give it room and read the chart.</p>`,
        illustration: () => S.cardinalCompass(),
        caption: 'Four cardinal marks around one danger. Each mark stands in the quadrant it is named after, and you pass on that side. Cones point towards the black band.',
        keyFacts: ['Quadrants bounded by NW–NE, NE–SE, SE–SW, SW–NW from the danger; a mark is named after the quadrant it stands in', 'Pass on the NAMED side: north of a north cardinal, east of an east cardinal, and so on', 'N: black over yellow, cones up. E: black-yellow-black, cones base to base. S: yellow over black, cones down. W: yellow-black-yellow, cones point to point', 'Cones point towards the black; topmarks always black, light always white', 'Danger extent is not shown: read the chart'],
        check: { id: 'buoyage-c4', q: 'A pillar buoy is painted black above yellow and carries two black cones, both pointing up. Where is the safe water?', options: ['South of the mark', 'East of the mark', 'North of the mark', 'All around the mark'], answer: 2, explanation: 'Black over yellow with cones pointing up is a north cardinal mark. It stands north of the danger and you pass north of it (F20, F23).' },
      },
      // 5 ------------------------------------------------------------
      {
        id: 'cardinal-lights',
        title: 'Cardinal lights at night: the clock face',
        html: `<p>At night a cardinal mark shows a <strong>white</strong> light that flashes <strong>quick (Q)</strong> or <strong>very quick (VQ)</strong>. Quick means <strong>50 or 60 flashes a minute</strong> (the chart range is 50–79); very quick means <strong>100 or 120 a minute</strong> (range 80–159). The number of flashes in each group tells you the mark, and the memory aid is a clock face:</p>
<div class="table-wrap"><table><thead><tr><th>Mark</th><th>Clock</th><th>Quick version</th><th>Very quick version</th></tr></thead><tbody>
<tr><td>North</td><td>12</td><td>Q, continuous</td><td>VQ, continuous</td></tr>
<tr><td>East</td><td>3</td><td>Q(3) every 10 s</td><td>VQ(3) every 5 s</td></tr>
<tr><td>South</td><td>6</td><td>Q(6) + long flash every 15 s</td><td>VQ(6) + long flash every 10 s</td></tr>
<tr><td>West</td><td>9</td><td>Q(9) every 15 s</td><td>VQ(9) every 10 s</td></tr>
</tbody></table></div>
<p>The south mark adds a <strong>long flash of at least 2 seconds</strong> after its six quick flashes so that a count of six cannot be mistaken for three or nine. On the chart the periods 5 s, 10 s and 15 s of cardinal lights may be left out, so "VQ(3)" alone still means an east cardinal.</p>
<p>So the night-time drill is: count the white flashes in a group, then wait for the pause. Three then a pause: east, pass east of it. Six and a long one: south. Nine: west. No pause at all, just an unbroken string of quick flashes: north. Then check the chart for the danger the mark guards. Remember that a <strong>white Fl(2)</strong>, two flashes with a long dark gap, is not a cardinal but an <strong>isolated danger</strong> mark, and that any <strong>coloured</strong> flashing light is some other mark.</p>
<div class="callout rule"><p>White light, Q or VQ in groups: 3 = east, 6 (+ long flash) = south, 9 = west, continuous = north.</p></div>`,
        illustration: () => cardinalRhythms(),
        caption: 'One 15-second timeline for each cardinal light in its quick (Q) version. North never pauses; east pauses after 3; south adds a long flash after 6; west pauses after 9.',
        keyFacts: ['Cardinal lights are WHITE, quick (50 or 60/min) or very quick (100 or 120/min)', 'N = continuous Q or VQ; E = Q(3) 10s or VQ(3) 5s; S = Q(6)+LFl 15s or VQ(6)+LFl 10s; W = Q(9) 15s or VQ(9) 10s', 'The long flash (2 s or more) after six flashes stops 6 being confused with 3 or 9', 'Clock face: 3 = east, 6 = south, 9 = west, 12 = north (continuous)', 'White Fl(2) is an isolated danger mark, not a cardinal'],
        check: { id: 'buoyage-c5', q: 'At night you count nine quick white flashes, then darkness, and the pattern repeats every 15 seconds. What is the mark and where do you pass?', options: ['East cardinal: pass east of it', 'South cardinal: pass south of it', 'West cardinal: pass west of it', 'Isolated danger: pass on either side'], answer: 2, explanation: 'Q(9) 15s is the west cardinal light: nine flashes, nine o\'clock, west. The safe water lies west of the mark (F26, F28).' },
      },
      // 6 ------------------------------------------------------------
      {
        id: 'other-marks',
        title: 'Isolated danger, safe water, special and emergency wreck marks',
        html: `<p>Four more marks complete the system. An <strong>isolated danger mark</strong> is placed on, or moored over, a small danger such as a rock with <strong>navigable water all around</strong>. It is <strong>black with one or more broad red horizontal bands</strong>, carries <strong>two black spheres</strong> one above the other, and shows a <strong>white group-flashing light Fl(2)</strong>. You may pass it on any side, but at a safe distance, because the mark does not show how far the danger extends.</p>
<p>A <strong>safe water mark</strong> says the opposite: there is <strong>navigable water all around and it marks no danger</strong>. It is used as a mid-channel, fairway or landfall mark, or to show the best point of passage under a bridge. It has <strong>red and white vertical stripes</strong>, is spherical or carries a <strong>single red sphere</strong> topmark, and shows a white light that is <strong>isophase, occulting, one long flash every 10 s or Morse "A"</strong>. It is the only mark type with red and white vertical stripes.</p>
<p>A <strong>special mark</strong> is <strong>yellow</strong>, with a <strong>yellow X</strong> topmark if any and a <strong>yellow light</strong> in any rhythm not used for white lights. It marks an area or feature explained on the chart: fish farms, cables and pipelines, bathing areas, military exercise areas, anchorages, mooring buoys. Its shape must not contradict the lateral system, so a special mark on the port side of a channel may be can-shaped but never conical. Fish farms are marked at their outer points with yellow special marks no more than 200 m apart showing <strong>Oc Y 2s</strong>.</p>
<p>The <strong>emergency wreck marking buoy</strong> marks a <strong>new danger</strong> not yet on the chart: <strong>blue and yellow vertical stripes</strong> (4 to 8 of them), a <strong>yellow upright cross (+)</strong> on top, and an <strong>alternating light, 1 s blue, 1 s yellow</strong> with half a second dark between.</p>
<div class="callout warn"><p>Fl(2) white = isolated danger. Fl(2+1) = preferred channel (not used in Norway). Yellow X = special; yellow + = wreck. Horizontal bands = danger-type marks; vertical stripes = safe water or new wreck.</p></div>`,
        illustration: () => dangerRow(),
        caption: 'Left to right: isolated danger (black, red band, two black balls, Fl(2) W), safe water (red/white vertical stripes, red ball), special (yellow, yellow X, yellow light) and the emergency wreck buoy (blue/yellow vertical stripes, yellow +, alternating blue/yellow light).',
        keyFacts: ['Isolated danger: black with red band(s), two black spheres, white Fl(2); water all around, pass either side at a safe distance', 'Safe water: red/white VERTICAL stripes, one red sphere, white Iso, Oc, LFl 10s or Mo(A); navigable all around, mid-channel or landfall', 'Special: yellow, yellow X, yellow light (typically Fl(4) Y in Norway); fish farms, cables, bathing areas, anchorages, military areas', 'Fish farms: yellow special marks at the outer points, max 200 m apart, light Oc Y 2s', 'Emergency wreck buoy: blue/yellow vertical stripes, yellow +, light 1 s blue / 1 s yellow'],
        check: { id: 'buoyage-c6', q: 'Which white light rhythm belongs to an isolated danger mark?', options: ['Fl(2+1)', 'Fl(2)', 'Iso', 'Q(3) 10s'], answer: 1, explanation: 'Isolated danger marks show a white group flash of two, Fl(2). Fl(2+1) is the preferred channel rhythm, Iso is a safe water rhythm and Q(3) 10s is the east cardinal (F33, F36, F17, F24).' },
      },
      // 7 ------------------------------------------------------------
      {
        id: 'norwegian-spars',
        title: 'Norwegian spar buoys: reading colour, top shape and reflectors',
        html: `<p>Because most Norwegian spars carry no topmark, you must identify them by <strong>colour bands and the shape of the top</strong>. For laterals you already know the rule: red blunt, green pointed. For cardinals the rule is just as simple: spars that are <strong>black at the top (north and east) have a pointed top</strong>; spars that are <strong>yellow at the top (south and west) have a blunt top</strong>. So a black-over-yellow spar with a pointed top is a north cardinal; a yellow-over-black spar with a flat top is a south cardinal; a black–yellow–black pointed spar is east; a yellow–black–yellow blunt spar is west. The top shape confirms what the colours already say, which helps when paint has faded or the light is poor.</p>
<p>At night the colours are shown by <strong>reflective tape</strong>, normally 20 cm wide, in the colour of the field it sits on, with one exception: <strong>blue tape stands for black</strong>, because black does not reflect. The reflector bands are near the top of the spar. Cardinals: north one blue band over one yellow band; east two blue bands; south one yellow over one blue; west two yellow bands. Isolated danger: blue over red. Safe water: red over white. Special: one yellow band. Laterals: one red or one green band. A searchlight on a spar therefore shows you its identity even when the paint is invisible.</p>
<div class="callout warn"><p>Blue reflective tape means <em>black paint</em> on a Norwegian mark. A buoy with blue and yellow painted <em>stripes</em> is something else entirely: the emergency wreck buoy.</p></div>
<p>One more reminder that applies to every floating mark: it swings on its mooring inside a "watch circle", it may drift, capsize or lose its light, and its charted position is only approximate because buoys are checked periodically, sometimes a year apart. Use buoys as signposts, not as fixed reference points, and never pass close to any mark, because the danger it guards and its mooring are right beside it.</p>`,
        illustration: () => S.sparRule(),
        caption: 'Six Norwegian spars without topmarks. Laterals: red blunt, green pointed. Cardinals: black on top (N, E) pointed, yellow on top (S, W) blunt. Reflective bands near the top show the colours at night; blue stands for black.',
        keyFacts: ['Cardinal spars: black at the top (N, E) = pointed; yellow at the top (S, W) = blunt', 'Lateral spars: red = blunt, green = pointed', 'Reflective tape (20 cm) in the field colour; BLUE tape stands for black', 'Reflectors: N blue/yellow, E two blue, S yellow/blue, W two yellow, isolated danger blue/red, safe water red/white, special yellow', 'Floating marks can drift or be extinguished; positions are approximate; never pass close to a mark'],
        check: { id: 'buoyage-c7', q: 'You see a spar painted yellow above black with a flat (blunt) top and no topmark. What is it?', options: ['A north cardinal mark: pass north of it', 'A west cardinal mark: pass west of it', 'A special mark: it shows a bathing area', 'A south cardinal mark: pass south of it'], answer: 3, explanation: 'Yellow over black is the south cardinal, and the blunt top confirms a yellow-topped cardinal. The danger lies north of it; pass to the south (S2, F25, F30).' },
      },
      // 8 ------------------------------------------------------------
      {
        id: 'fixed-marks',
        title: 'Fixed marks: poles with pointers, cairns, beacons and lanterns',
        html: `<p>Norway's almost 12,000 fixed unlit marks come in three families. <strong>Iron poles</strong> stand on or right beside small rocks and shallows. <strong>Cairns</strong> are piles of stone or concrete built on skerries that are always visible. <strong>Lattice beacons</strong> are larger wooden or iron structures on land, visible from further away. Cairns and beacons have no standard colour by type: they are painted to contrast with their surroundings in summer and winter.</p>
<p>The exam's favourite fixed mark is the <strong>pole with a pointer</strong>: an iron pole with a horizontal arm near the top. <strong>The arm points towards the navigable (deep) water.</strong> Pass on the side the arm points to, keeping the pole and its rock on the other side. A pole that may be passed on <strong>both sides carries two arms</strong>, one to each side. The reflector on a pointer follows the direction of buoyage: <strong>red</strong> on a pole to be left to port, <strong>green</strong> on one to be left to starboard, and a <strong>white reflector</strong> means the mark can be passed on either side.</p>
<div class="callout warn"><p>Ice, storms and collisions bend pointer arms, so a pointer can point the wrong way. Never trust it blindly: the chart shows where the rock really is.</p></div>
<p>Many fixed marks also carry small lights. <strong>Lanterns</strong> on poles, tripods, columns or cairns are usually all-round white, red or green and, being solar powered, mostly show Q or Fl with short range; red and green lanterns stand at the outer edge of an obstruction, green on the starboard side and red on the port side in the main direction, while a white lantern may sit on top of the obstruction to mark its position. The <strong>high-speed-craft mark with indirect lighting (HIB)</strong> is a pole with a lantern on top and a floodlit white cone lower down that <strong>points towards the fairway</strong>. The cone carries a number and a reflector: <strong>even numbers with a red reflector are kept to port, odd numbers with a green reflector to starboard</strong> in the main direction; a white reflector means either side.</p>`,
        illustration: () => S.pointerPole('left'),
        caption: 'A pole with a pointer: the arm points towards deep water, so you pass on that side. Two arms and a white reflector would mean "either side".',
        keyFacts: ['Pointer arm points TOWARDS navigable water: pass on the side it points to', 'Two arms (and a white reflector) = can be passed on both sides', 'Reflector: red = leave to port, green = leave to starboard, white = either side', 'Pointers can be bent by ice and collisions: always check the chart', 'HIB mark: lantern on top, floodlit cone pointing to the fairway; even/red = port, odd/green = starboard', 'Cairns and beacons have no colour code; iron poles stand on the rock itself'],
        check: { id: 'buoyage-c8', q: 'An iron pole stands on a rock ahead, and its arm points to your right. Where do you pass?', options: ['To the left of the pole', 'To the right of the pole, where the arm points', 'Straight over the rock; the pole marks deep water', 'Either side, because a single arm means both sides are clear'], answer: 1, explanation: 'The pointer points towards navigable water, so pass to the right, leaving the pole and its rock on your left. Only a pole with two arms may be passed on both sides (F50, S8).' },
      },
      // 9 ------------------------------------------------------------
      {
        id: 'light-characters',
        title: 'Light characters and how to read a light on the chart',
        html: `<p>Every lit aid has a <strong>character</strong>, the rhythm it shows, written on the chart in a short code. A <strong>lighthouse</strong> is a tower or building with a light of long or medium range, <strong>nominal range 10 nautical miles or more</strong>; a <strong>minor light</strong> is a small structure, in Norway a white house with a red roof that doubles as a daymark, and most minor lights are sector lights. Learn these codes:</p>
<div class="table-wrap"><table><thead><tr><th>Code</th><th>Name</th><th>What you see</th></tr></thead><tbody>
<tr><td>F</td><td>Fixed</td><td>Steady light</td></tr>
<tr><td>Oc, Oc(2)</td><td>Occulting</td><td>Light LONGER than dark: a steady light briefly switched off</td></tr>
<tr><td>Iso</td><td>Isophase</td><td>Light and dark of EQUAL length</td></tr>
<tr><td>Fl, Fl(3)</td><td>Flashing</td><td>Light SHORTER than dark; (3) = group of three</td></tr>
<tr><td>LFl</td><td>Long flash</td><td>A flash of 2 s or longer</td></tr>
<tr><td>Q / VQ / UQ</td><td>Quick / very quick / ultra quick</td><td>50–79 / 80–159 / 160 or more flashes a minute</td></tr>
<tr><td>Fl(2+1)</td><td>Composite group flashing</td><td>Two flashes, then one; preferred channel only</td></tr>
<tr><td>Mo(A)</td><td>Morse code</td><td>Short-long, the letter A</td></tr>
<tr><td>Al WR</td><td>Alternating</td><td>Steady light changing colour</td></tr>
</tbody></table></div>
<p>A full chart description reads like <strong>"Fl(3) WRG 15s 21m 15-11M"</strong>: group flashing, three flashes; white, red and green sectors; <strong>period 15 s</strong> (one full cycle of light and dark); <strong>elevation 21 m above mean high water</strong>; <strong>nominal range</strong> white 15 M, green 11 M, red between 15 and 11 M. Colour letters are W white, R red, G green, Y yellow, Bu blue. Nominal range is the range in a visibility of 10 nautical miles; fog, haze and snow shorten it, and the geographical range in the list of lights assumes an eye height of 5 m. Bridge and cable clearances, by contrast, are referred to highest astronomical tide (HAT).</p>
<div class="callout tip"><p>Oc is "mostly on", Fl is "mostly off", Iso is "half and half". If the chart says Oc you will see a light that blinks <em>off</em>.</p></div>`,
        illustration: () => S.lightDecoder(),
        caption: 'Fl(3) WRG 15s 21m 15-11M decoded: group flashing three, white/red/green sectors, period 15 s, 21 m above mean high water, nominal range white 15 M, green 11 M, red between.',
        keyFacts: ['Oc = light longer than dark; Iso = equal; Fl = light shorter than dark; LFl = flash of 2 s or more', 'Q = 50-79/min (usually 50 or 60); VQ = 80-159/min (usually 100 or 120); UQ = 160 or more', 'Period = time for one full cycle; elevation = metres above MEAN HIGH WATER; range = nominal, in 10 M visibility', '"15-11M" = white 15 M, green 11 M, red between', 'Lighthouse: nominal range 10 M or more; minor light: small white house with red roof, usually a sector light'],
        check: { id: 'buoyage-c9', q: 'A chart shows a light as "Oc WRG 6s 12m 9-6M". Which statement is correct?', options: ['The light flashes briefly every 6 seconds and is 12 m deep', 'The light is fixed white, red and green and 6 m high', 'The light shows a 6-second flash every 12 seconds and is visible 9 to 6 km', 'The light is on most of the time with short dark gaps, period 6 s, 12 m above mean high water, white range 9 M, green 6 M'], answer: 3, explanation: 'Oc = occulting: light longer than dark. 6s is the period, 12m the elevation above mean high water, 9-6M the nominal range white 9 M, green 6 M, red between (S5, F90, F97).' },
      },
      // 10 ------------------------------------------------------------
      {
        id: 'sector-lights',
        title: 'Sector lights: white is the fairway, red to port, green to starboard',
        html: `<p>A <strong>sector light</strong> shows different colours over different angles from one fixed lamp, so that the colour you see tells you where you are. Three colours are used, <strong>white, red and green</strong> (some lights have only two). The <strong>white sector marks the fairway</strong>: navigable water for the vessels expected to use it. <strong>Red and green sectors mark foul water</strong>. But a white sector shows clear water only within a limited area: <strong>shoals can still lie inside it</strong>, so read the sector light together with the chart and the other marks.</p>
<p>Since the Norwegian Coastal Administration converted about 1,800 sector lights to the IALA standard (completed on 11 November 2025), one rule applies everywhere as far as local waters allow: <strong>when you steer towards a light in its white sector, the sector on your starboard side is green and the sector on your port side is red</strong>. That gives you an automatic correction:</p>
<ul>
<li>Heading for the light and it turns <strong>green</strong>: you have strayed to <strong>starboard</strong>; <strong>alter course to port</strong> until it is white again.</li>
<li>Heading for the light and it turns <strong>red</strong>: you have strayed to <strong>port</strong>; <strong>alter course to starboard</strong>.</li>
<li>Light <strong>astern</strong>: the picture is mirrored. Green now lies on your port side and red on your starboard side, so red astern means turn to <strong>port</strong>.</li>
</ul>
<p>Sector limits on the chart and in the list of lights are <strong>true bearings from the sea towards the light</strong>, 0° to 360° clockwise from north. Between sectors there is a small transition angle, typically about 2°, where the colour is uncertain, and between red and green there is a narrow band that looks white. Wet or frosted lantern glass can shift the boundaries and make colours look pale. On multicoloured Norwegian charts the white sector is drawn as a <strong>yellow arc</strong>, red and green as red and green arcs.</p>
<div class="callout warn"><p>Old textbooks and uncorrected charts may still show the pre-2025 sectors. Use an updated chart, and never treat a white sector as a promise of deep water.</p></div>`,
        illustration: () => S.sectorLight({ preset: 'fairway' }),
        caption: 'Heading for the light in the white sector: green on your starboard hand, red on your port hand. Drift into green, turn to port; drift into red, turn to starboard. Rocks lie under the coloured sectors.',
        keyFacts: ['White sector = fairway (shoals may still occur inside it); red and green = foul water', 'Heading TOWARDS the light: green on your starboard side, red on your port side (IALA rule, all Norwegian lights since 11 Nov 2025)', 'Light turns green: you are too far to starboard, turn to port. Turns red: too far to port, turn to starboard', 'Light astern: mirrored (red astern means turn to port)', 'Sector limits are TRUE bearings from the sea towards the light; transition about 2 degrees; white drawn as a yellow arc on colour charts'],
        check: { id: 'buoyage-c10', q: 'You are steering towards a minor light at night in its white sector. The light turns green. What do you do?', options: ['Alter course to port until the light is white again', 'Alter course to starboard until the light is white again', 'Keep going: green means the water is safe', 'Stop and anchor; a green sector means a prohibited area'], answer: 0, explanation: 'Heading for the light, green lies on your starboard side of the white sector. Seeing green means you have drifted to starboard, so turn to port (S6, F64, F65).' },
      },
      // 11 ------------------------------------------------------------
      {
        id: 'leading-lines',
        title: 'Leading lines, floodlights and bridge marking',
        html: `<p>A <strong>leading line</strong> is two marks or lights that appear <strong>exactly one above the other</strong> when you are on the correct track. The <strong>front mark is lower</strong>, the <strong>rear mark is higher</strong>. Daymarks may be two lattice beacons, two red squares, or two triangles with the <strong>front one apex up and the rear one apex down</strong>. Leading lights may be white, red or yellow, preferably not fixed. On the chart the line is drawn solid where it is the track to follow and dashed beyond, with its bearing in degrees and tenths, for example "Ldg 025.5°", normally the direction towards the marks.</p>
<p>Drift off the line and the marks separate sideways. Because the near front mark swings across your view faster than the distant rear mark, <strong>the rear mark appears displaced towards the side you are on</strong>. Rear mark to the right of the front mark: you are right of the line, <strong>steer left</strong>. Rear mark to the left: you are left of the line, <strong>steer right</strong>. Steer from the rear mark towards the front mark.</p>
<p><strong>Indirect lighting</strong> is a <strong>fixed yellow floodlight</strong> that illuminates a headland, skerry, breakwater head or bridge pier. You see the lit object, not the lamp, which gives "daylight navigation" and better distance judgement in the dark.</p>
<p><strong>Bridges</strong> over navigable water are marked like a channel: <strong>red and green lights</strong> on the sides of the navigable span, <strong>white lights</strong> at the centre of the span, and floodlit piers. Signs on the bridge repeat the message: a <strong>green triangle (apex up)</strong> marks the starboard side of the span and a <strong>red square</strong> the port side, relative to the direction of buoyage, while a <strong>circle with red and white vertical stripes</strong> (the safe-water colours) shows the <strong>best point of passage</strong>; a safe water mark may also be used for that. The charted <strong>vertical clearance</strong> under a bridge or power line is referred to <strong>highest astronomical tide</strong>, the worst case for your mast.</p>`,
        illustration: () => S.leadingLine(),
        caption: 'Rear mark exactly above the front mark: on the line. Rear mark to the left: you are left of the line, steer right. Rear mark to the right: you are right, steer left.',
        keyFacts: ['Leading line: front mark lower (triangle apex up), rear mark higher (apex down); in line = on track; bearing in degrees and tenths', 'Rear mark appears displaced towards the side YOU are on: rear right = you are right, steer left', 'Indirect lighting = fixed yellow floodlight on the object; you see the object, not the lamp', 'Bridge: green triangle = starboard side of span, red square = port side, red/white striped circle = best point of passage; white light at the centre', 'Bridge clearance is referred to highest astronomical tide (HAT)'],
        check: { id: 'buoyage-c11', q: 'Approaching on a leading line, the upper (rear) mark appears to the right of the lower (front) mark. Where are you and what do you do?', options: ['Right of the line: steer left', 'Left of the line: steer right', 'On the line: hold your course', 'Too close to the marks: slow down'], answer: 0, explanation: 'The rear mark appears displaced towards the side you are on. Rear mark to the right means you are right of the line, so steer left, bringing the rear mark back over the front one (S12).' },
      },
      // 12 ------------------------------------------------------------
      {
        id: 'on-the-chart',
        title: 'Marks and lights on the chart, and the classic traps',
        html: `<p>Norwegian charts use their own symbols for buoys, spar buoys, beacons and poles, and <strong>topmarks are not charted</strong>, so you read the <strong>colour abbreviations</strong> beside the symbol: <strong>BY</strong> black over yellow = north cardinal, <strong>BYB</strong> = east, <strong>YB</strong> = south, <strong>YBY</strong> = west, <strong>BRB</strong> = isolated danger, <strong>RW</strong> = safe water, <strong>Y</strong> = special, <strong>R</strong> and <strong>G</strong> = laterals. The lateral system applies to all fixed and floating marks <em>except</em> lighthouses, landfall lights, leading lights and marks, sector lights and large light-floats, which are described individually. A lit aid carries a <strong>magenta flare</strong>; a sector light is drawn with coloured arcs, the white sector as a <strong>yellow arc</strong>; the direction of buoyage, where needed, is a <strong>magenta arrow</strong>. Sector limits and leading lines use true bearings.</p>
<p>Faults in marks and lights should be reported to the Coastal Administration's navigational warning coordinator, and all changes are published in the Norwegian Notices to Mariners every 14 days: keep your chart corrected.</p>
<h4>The traps that cost part-4 points</h4>
<ul>
<li>"Red right returning" is Region B. In Norway red is to <strong>port</strong> when returning from sea.</li>
<li>A cardinal mark's name is the side to <strong>pass on</strong>, not where the danger is.</li>
<li>East topmark = egg (base to base), west = wineglass (point to point).</li>
<li>Fl(2) white = isolated danger; Fl(2+1) = preferred channel.</li>
<li>Yellow X = special mark; yellow + = emergency wreck buoy.</li>
<li>Most Norwegian spars have no topmark: red blunt, green pointed; black-topped cardinals pointed, yellow-topped blunt.</li>
<li>The white sector is not a guarantee of deep water; colours are defined for a boat <strong>heading towards</strong> the light.</li>
<li>Sector limits are true bearings <strong>from the sea</strong> towards the light.</li>
<li>Light elevation is above mean high water; bridge clearance above HAT; range on the chart is nominal.</li>
<li>Oc is mostly light, Fl mostly dark, Iso equal.</li>
<li>A pointer arm points towards deep water, and it can be bent.</li>
<li>Even numbers red/port, odd numbers green/starboard, also on HIB marks.</li>
</ul>`,
        illustration: () => S.chartExcerpt(),
        caption: 'An invented chart excerpt: lateral buoys with the magenta direction-of-buoyage arrow, a sector light with its coloured arcs (white drawn yellow), a leading line, rocks and soundings.',
        keyFacts: ['Chart abbreviations: BY north, BYB east, YB south, YBY west, BRB isolated danger, RW safe water, Y special, R/G laterals; topmarks not charted', 'Magenta flare = lit aid; white sector = yellow arc on colour charts; magenta arrow = direction of buoyage', 'Exceptions to the IALA system: lighthouses, landfall lights, leading lights/marks, sector lights, large light-floats', 'Changes are published in the Norwegian Notices to Mariners every 14 days', 'Trap list above: swap sides when leaving harbour, east egg / west wineglass, Fl(2) vs Fl(2+1), X vs +'],
        check: { id: 'buoyage-c12', q: 'Beside a buoy symbol on a Norwegian chart you read "BYB". What is the mark?', options: ['A west cardinal mark', 'An isolated danger mark', 'An east cardinal mark', 'A safe water mark'], answer: 2, explanation: 'Colour letters read top to bottom: B black, Y yellow, B black is black-yellow-black, the east cardinal. West is YBY, isolated danger BRB, safe water RW (F103).' },
      },
    ],
    flashcards: [
      { front: 'Which IALA region is Norway in, and what differs between A and B?', back: 'Region A. Only lateral (and preferred channel) marks differ; all other marks are identical worldwide.' },
      { front: 'Direction of buoyage?', back: 'From seaward into harbours and fjords; along the coast clockwise round Norway (west along the south coast, north up the west coast). Magenta arrow on the chart.' },
      { front: 'Port-hand lateral mark (Region A)?', back: 'Red, can-shaped, red can topmark, red light (any rhythm except Fl(2+1)). Keep to port with the direction of buoyage.' },
      { front: 'Starboard-hand lateral mark?', back: 'Green, conical, green cone topmark, green light (any rhythm except Fl(2+1)). Keep to starboard with the direction of buoyage.' },
      { front: 'Leaving harbour: which side is a red mark?', back: 'On your starboard side. Against the direction of buoyage the lateral rule reverses.' },
      { front: 'Lateral numbering?', back: 'Even numbers on red (port) marks, odd on green (starboard), counting from seaward.' },
      { front: 'Norwegian red spar vs green spar without topmarks?', back: 'Red has a blunt (flat) top; green has a pointed top. One reflective band in the mark colour.' },
      { front: 'Fixed lateral pole in Norway?', back: 'White with a red band (port) or a green band (starboard). On a fixed beacon only the topmark shape has meaning.' },
      { front: 'Which light rhythm may an ordinary lateral mark NOT show?', back: 'Fl(2+1), reserved for preferred channel marks (which are not used in Norway).' },
      { front: 'North cardinal mark?', back: 'Black over yellow, two cones points up, white Q or VQ continuous. Pass north of it.' },
      { front: 'East cardinal mark?', back: 'Black-yellow-black, two cones base to base, white Q(3) 10s or VQ(3) 5s. Pass east of it.' },
      { front: 'South cardinal mark?', back: 'Yellow over black, two cones points down, white Q(6)+LFl 15s or VQ(6)+LFl 10s. Pass south of it.' },
      { front: 'West cardinal mark?', back: 'Yellow-black-yellow, two cones point to point, white Q(9) 15s or VQ(9) 10s. Pass west of it.' },
      { front: 'Rule for cardinal topmarks?', back: 'The cones point towards the black band: up = N, down = S, outward (base to base) = E, inward (point to point) = W.' },
      { front: 'Clock-face rule for cardinal lights?', back: '3 flashes = 3 o\'clock = east; 6 (+ long flash) = south; 9 = west; continuous = north.' },
      { front: 'Why the long flash after six quick flashes?', back: 'So that six cannot be confused with three or nine (IALA). Long flash = 2 s or more.' },
      { front: 'Quick and very quick flash rates?', back: 'Q = 50 or 60 per minute (chart range 50-79); VQ = 100 or 120 per minute (range 80-159).' },
      { front: 'Norwegian cardinal spars without topmarks: top shape?', back: 'Black at the top (N, E) = pointed; yellow at the top (S, W) = blunt.' },
      { front: 'Blue reflective tape on a Norwegian mark?', back: 'Stands for black paint (black does not reflect). Tape is normally 20 cm wide.' },
      { front: 'Isolated danger mark?', back: 'Black with red horizontal band(s), two black spheres, white Fl(2). Water all around: pass either side at a safe distance.' },
      { front: 'Safe water mark?', back: 'Red/white vertical stripes, one red sphere, white Iso, Oc, LFl 10s or Mo(A). Navigable all around; mid-channel, landfall, best passage under a bridge.' },
      { front: 'Special mark?', back: 'Yellow, yellow X topmark, yellow light (typically Fl(4) Y). Fish farms, cables, bathing areas, anchorages, military areas.' },
      { front: 'Emergency wreck marking buoy?', back: 'Blue/yellow vertical stripes (4-8), yellow upright cross, light 1 s blue / 1 s yellow with 0.5 s dark. A new danger.' },
      { front: 'Fish farm marking?', back: 'Yellow special marks at the outer points, at most 200 m apart, light Oc Y 2s, synchronised.' },
      { front: 'Pole with a pointer arm?', back: 'The arm points TOWARDS navigable water: pass on that side. Two arms and a white reflector = either side. Pointers can be bent: check the chart.' },
      { front: 'HIB mark number 12 with a red reflector?', back: 'Even number + red reflector: keep it to port in the main direction. Odd + green = starboard; white = either side.' },
      { front: 'White sector of a sector light?', back: 'The fairway for the intended traffic. Shoals can still occur inside it: read the chart. Red and green = foul water.' },
      { front: 'Heading towards a sector light: which colour is on which side?', back: 'Green on your starboard side, red on your port side (IALA rule applied to all Norwegian lights since 11 Nov 2025).' },
      { front: 'Heading for the light, it turns red. Action?', back: 'You have drifted to port: alter course to starboard until it shows white. Green: drifted to starboard, alter to port.' },
      { front: 'Sector light astern turns red. Action?', back: 'Mirrored: red lies on your starboard side, so turn to port.' },
      { front: 'How are sector limits stated?', back: 'True bearings from the sea towards the light, 0 to 360 clockwise from north.' },
      { front: 'Oc, Iso, Fl, LFl?', back: 'Oc: light longer than dark. Iso: equal. Fl: light shorter than dark. LFl: flash of 2 s or longer.' },
      { front: '"Fl(3) WRG 15s 21m 15-11M"?', back: 'Group flashing 3; white/red/green sectors; period 15 s; 21 m above mean high water; nominal range white 15 M, green 11 M, red between.' },
      { front: 'Nominal range?', back: 'Range in a meteorological visibility of 10 nautical miles. Fog and snow reduce it. A lighthouse has 10 M or more.' },
      { front: 'Leading line: rear mark appears right of the front mark?', back: 'You are right of the line: steer left. The rear mark is displaced towards the side you are on.' },
      { front: 'Bridge signs?', back: 'Green triangle = starboard side of the span, red square = port side, circle with red/white vertical stripes = best point of passage. Clearance referred to HAT.' },
      { front: 'Indirect lighting?', back: 'A fixed yellow floodlight illuminating a headland, skerry or pier: you see the object, not the lamp.' },
      { front: 'Chart abbreviations BY, BYB, YB, YBY, BRB, RW?', back: 'North, east, south, west cardinal; isolated danger; safe water. Topmarks are not charted on Norwegian charts.' },
    ],
    questions: [
      // ---- part 4, item 1.4.1: lateral and cardinal systems, special marks, pole with pointer ----
      { id: 'buoyage-01', q: 'You are entering a harbour from the sea and this buoy lies ahead. What is it and on which side do you keep it?', illustration: () => qmark('lateral-port', { light: true }), options: ['A port-hand lateral mark: keep it on your left', 'A starboard-hand lateral mark: keep it on your right', 'An isolated danger mark: pass either side at a distance', 'A special mark: it has no navigational meaning'], answer: 0, explanation: 'A red can buoy with a red can topmark is the Region A port-hand mark. Entering from seaward is the direction of buoyage, so it stays on your port (left) side (F10, F12).', difficulty: 1, part: 4, p4: '1.4.1', tags: ['lateral', 'picture'] },
      { id: 'buoyage-02', q: 'What is this mark, and where does it belong when you travel in the direction of buoyage?', illustration: () => qmark('lateral-starboard', { light: true }), options: ['A special mark marking a fish farm', 'A north cardinal mark; pass north of it', 'A safe water mark; pass either side', 'A starboard-hand lateral mark; keep it on your right'], answer: 3, explanation: 'Green, conical, with a green cone topmark and a green light: the starboard-hand mark. With the direction of buoyage it is kept to starboard (F11, F12).', difficulty: 1, part: 4, p4: '1.4.1', tags: ['lateral', 'picture'] },
      { id: 'buoyage-03', q: 'You are leaving a harbour and heading out to sea. A red lateral mark lies ahead. On which side do you keep it?', options: ['On your starboard side, because you are travelling against the direction of buoyage', 'On your port side, as always for red marks', 'Either side; red marks only matter when entering', 'You must not pass it at all'], answer: 0, explanation: 'The direction of buoyage runs from seaward in. Leaving, you travel against it and the rule reverses: red to starboard, green to port (F12, S1).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['lateral', 'direction'] },
      { id: 'buoyage-04', q: 'What is this mark and where is the safe water?', illustration: () => qmark('cardinal-n', { light: true }), options: ['South cardinal: safe water south of it', 'North cardinal: safe water north of it', 'Isolated danger: safe water all around', 'East cardinal: safe water east of it'], answer: 1, explanation: 'Black over yellow with two cones pointing up is the north cardinal mark. It stands in the north quadrant of the danger; pass north of it (F20, F23).', difficulty: 1, part: 4, p4: '1.4.1', tags: ['cardinal', 'picture'] },
      { id: 'buoyage-05', q: 'Identify this mark and say on which side you pass it.', illustration: () => qmark('cardinal-e', { light: true }), options: ['West cardinal: pass west of it', 'South cardinal: pass south of it', 'East cardinal: pass east of it', 'Special mark: pass either side'], answer: 2, explanation: 'Black-yellow-black with the cones base to base (the "egg") is the east cardinal; safe water lies east of it (F24, F27).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['cardinal', 'picture'] },
      { id: 'buoyage-06', q: 'Where does the danger lie in relation to this mark?', illustration: () => qmark('cardinal-s', { light: true }), options: ['South of the mark', 'East of the mark', 'Directly beneath the mark', 'North of the mark'], answer: 3, explanation: 'Yellow over black with both cones pointing down is the south cardinal. It stands south of the danger, so the danger lies to its north and you pass south of it (F20, F25).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['cardinal', 'picture'] },
      { id: 'buoyage-07', q: 'What is this mark?', illustration: () => qmark('cardinal-w', { light: true }), options: ['East cardinal mark', 'Preferred channel mark', 'Isolated danger mark', 'West cardinal mark'], answer: 3, explanation: 'Yellow-black-yellow with the cones point to point (the "wineglass") is the west cardinal mark; pass west of it. The east mark has cones base to base (F26, F27).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['cardinal', 'picture'] },
      { id: 'buoyage-08', q: 'This Norwegian spar buoy has no topmark. What is it?', illustration: () => qmark('cardinal-s', { form: 'spar' }), options: ['A south cardinal mark: pass south of it', 'A north cardinal mark: pass north of it', 'A special mark: a bathing area', 'A west cardinal mark: pass west of it'], answer: 0, explanation: 'Yellow over black is the south cardinal, and the blunt top confirms a yellow-topped cardinal spar. Pass south of it (F25, F30, S2).', difficulty: 3, part: 4, p4: '1.4.1', tags: ['cardinal', 'spar', 'picture'] },
      { id: 'buoyage-09', q: 'What is this Norwegian spar buoy?', illustration: () => qmark('cardinal-n', { form: 'spar' }), options: ['A port-hand lateral mark', 'An east cardinal mark', 'A north cardinal mark', 'A south cardinal mark'], answer: 2, explanation: 'Black over yellow is the north cardinal; black-topped cardinal spars are pointed. Pass north of it (F23, F30).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['cardinal', 'spar', 'picture'] },
      { id: 'buoyage-10', q: 'Sailing into a fjord from the sea you meet this spar. What is it and where do you pass?', illustration: () => qmark('lateral-port', { form: 'spar' }), options: ['A starboard-hand mark: keep it on your right', 'A port-hand mark: keep it on your left', 'An isolated danger mark: keep well clear', 'A safe water mark: pass either side'], answer: 1, explanation: 'A red spar with a blunt top and one red reflective band is the Norwegian port-hand lateral mark. Going in from the sea it stays on your port side (F13, F14, F12).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['lateral', 'spar', 'picture'] },
      { id: 'buoyage-11', q: 'What does this mark tell you?', illustration: () => qmark('special', { light: true }), options: ['Keep it to port when entering from sea', 'It marks a special area or feature shown on the chart, such as a fish farm or bathing area', 'Safe water all around: a mid-channel mark', 'A newly discovered wreck'], answer: 1, explanation: 'A yellow mark with a yellow X topmark and yellow light is a special mark. It is not a channel or danger mark; the chart explains what it marks (F40, F42, S9).', difficulty: 1, part: 4, p4: '1.4.1', tags: ['special', 'picture'] },
      { id: 'buoyage-12', q: 'What colour of light may a special mark show?', options: ['White', 'Red', 'Yellow', 'Blue'], answer: 2, explanation: 'Special marks are yellow and may only carry a yellow light, in any rhythm not used for white lights; in Norway typically Fl(4) Y (F40, F41).', difficulty: 1, part: 4, p4: '1.4.1', tags: ['special'] },
      { id: 'buoyage-13', q: 'Which of these is a typical use of a yellow special mark in Norway?', options: ['Marking the outer points of a fish farm', 'Marking the port side of a fairway', 'Marking a rock with navigable water all around', 'Marking the centre of a fairway'], answer: 0, explanation: 'Aquaculture facilities must have their outer points marked with yellow IALA special marks no more than 200 m apart, light Oc Y 2s. Channel sides are laterals, isolated rocks are isolated danger marks, fairway centres are safe water marks (F42, F44).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['special'] },
      { id: 'buoyage-14', q: 'An iron pole stands on a rock ahead of you. Where do you pass?', illustration: () => qpole(1), options: ['To the left of the pole', 'Either side; a pole with one arm can be passed on both sides', 'To the right of the pole, where the arm points', 'Directly over the rock; the pole marks deep water'], answer: 2, explanation: 'The pointer arm points towards navigable water, so pass on the right and keep the pole and its rock on your left. Two arms would mean either side (F50, S8).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['pointer', 'picture'] },
      { id: 'buoyage-15', q: 'What does the arm on a pole with a pointer indicate?', options: ['The direction of the nearest harbour', 'The direction of the danger: pass on the opposite side', 'The direction of the tidal stream', 'The direction of navigable water: pass on that side'], answer: 3, explanation: 'The pointer points towards navigable (deep) water. Where the mark can be passed on both sides it carries two arms (F50).', difficulty: 1, part: 4, p4: '1.4.1', tags: ['pointer'] },
      { id: 'buoyage-16', q: 'A pole on a rock has two pointer arms, one to each side, and a white reflector. What does that mean?', options: ['The mark may be passed on either side', 'The mark may not be passed at all', 'Pass on the left only; the right arm is a spare', 'The rock is only dangerous at low water'], answer: 0, explanation: 'Two arms mean the mark can be passed on both sides, and a white reflector on a topmark carries the same message. Red means leave to port, green leave to starboard (F50, F51).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['pointer'] },
      { id: 'buoyage-17', q: 'Why should you never rely on a pointer arm alone?', options: ['Pointer arms are only valid in daylight', 'Ice, storms and collisions can bend them so they point the wrong way; the chart shows the danger', 'They always point towards the rock, which confuses beginners', 'They are removed in winter'], answer: 1, explanation: 'Fixed marks can be damaged or twisted by weather and collisions, so a pointer can point the wrong way. Always check the chart (F52).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['pointer'] },
      { id: 'buoyage-18', q: 'Which topmark identifies an east cardinal mark?', options: ['Two black cones, both points up', 'Two black spheres', 'Two black cones, point to point', 'Two black cones, base to base'], answer: 3, explanation: 'East: cones base to base, points outward, matching black at the top and bottom of the mark. Up = north, down = south, point to point = west, two spheres = isolated danger (F24, F27).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['cardinal', 'topmark'] },
      { id: 'buoyage-19', q: 'Which cardinal mark is painted yellow with a single black band in the middle?', options: ['North', 'East', 'South', 'West'], answer: 3, explanation: 'West is yellow-black-yellow (the black band about a third of the height) with cones point to point. East is black-yellow-black (F26).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['cardinal'] },
      { id: 'buoyage-20', q: 'Where does a north cardinal mark stand in relation to the danger it marks?', options: ['North of the danger: you pass north of the mark', 'South of the danger: you pass south of the mark', 'On top of the danger', 'East of the danger'], answer: 0, explanation: 'A cardinal mark is placed in the quadrant it is named after, so a north cardinal stands north of the danger and the safe water is north of the mark (F20, F21).', difficulty: 1, part: 4, p4: '1.4.1', tags: ['cardinal'] },
      { id: 'buoyage-21', q: 'Lateral marks in a channel are numbered. What does an even number tell you?', options: ['The mark is green and kept to starboard', 'The mark is red and kept to port when going with the direction of buoyage', 'The mark is a cardinal mark', 'The number is the depth in metres'], answer: 1, explanation: 'Numbering follows the direction of buoyage: even numbers on red port-hand marks, odd numbers on green starboard-hand marks (F9).', difficulty: 1, part: 4, p4: '1.4.1', tags: ['lateral', 'numbers'] },
      { id: 'buoyage-22', q: 'A Norwegian cardinal spar buoy is black at the top. What shape is its top?', options: ['Blunt (flat)', 'Spherical', 'Pointed', 'Painted red'], answer: 2, explanation: 'Spars that are black at the top (north and east) have pointed tops; those yellow at the top (south and west) are blunt (F30).', difficulty: 3, part: 4, p4: '1.4.1', tags: ['cardinal', 'spar'] },
      { id: 'buoyage-23', q: 'A fixed iron pole on a rock is painted white with a green band. What is it?', options: ['A special mark', 'A north cardinal mark', 'A safe water mark', 'A starboard-hand lateral mark'], answer: 3, explanation: 'Norwegian fixed lateral marks are white with a red band (port) or a green band (starboard). Keep it to starboard when travelling with the direction of buoyage (F15).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['lateral', 'fixed'] },
      { id: 'buoyage-24', q: 'Which light rhythm may an ordinary red or green lateral mark NOT show?', options: ['Fl 3s', 'Iso', 'Q', 'Fl(2+1)'], answer: 3, explanation: 'Composite group flashing Fl(2+1) is reserved for preferred channel marks, which are not used in Norway. Any other rhythm is allowed for laterals (F10, F11, F17).', difficulty: 3, part: 4, p4: '1.4.1', tags: ['lateral', 'light'] },
      { id: 'buoyage-25', q: 'What rhythm does this white light show, and which mark carries it?', illustration: () => S.lightRhythm('Q(3) 10s', { color: 'W' }), options: ['Q(3) 10s: the east cardinal mark', 'Q(3) 10s: the west cardinal mark', 'Fl(3) 10s: a safe water mark', 'Q(3) 10s: a special mark'], answer: 0, explanation: 'Three quick white flashes every 10 s is Q(3) 10s, the east cardinal: three o\'clock = east. Special marks show yellow light; safe water uses Iso, Oc, LFl 10s or Mo(A) (F24, F28, S3).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['cardinal', 'light', 'picture'] },
      { id: 'buoyage-26', q: 'Which mark shows this light?', illustration: () => S.lightRhythm('Q(6)+LFl 15s', { color: 'W' }), options: ['North cardinal', 'East cardinal', 'West cardinal', 'South cardinal'], answer: 3, explanation: 'Six quick flashes followed by a long flash every 15 s is the south cardinal (six o\'clock). The long flash prevents confusion with three or nine (F25, F28).', difficulty: 2, part: 4, p4: '1.4.1', tags: ['cardinal', 'light', 'picture'] },
      { id: 'buoyage-27', q: 'At night you see an unbroken string of quick white flashes with no pause at all. What is the mark?', options: ['A north cardinal mark', 'A south cardinal mark', 'An isolated danger mark', 'A safe water mark'], answer: 0, explanation: 'Continuous Q or VQ white is the north cardinal (12 o\'clock, no group). Pass north of it (F23, F28).', difficulty: 1, part: 4, p4: '1.4.1', tags: ['cardinal', 'light'] },
      { id: 'buoyage-28', q: 'You pass a yellow can-shaped buoy on the port side of a channel. Why may a special mark be can-shaped but never conical there?', options: ['Cones are reserved for cardinal marks', 'Its shape must not contradict the lateral system: a cone would suggest a starboard mark', 'Cans float better than cones', 'Conical buoys may only be used offshore'], answer: 1, explanation: 'A special mark may have any shape that does not conflict with lateral marks. On the port side a can is acceptable; a cone would look like a starboard-hand mark (F43).', difficulty: 3, part: 4, p4: '1.4.1', tags: ['special'] },

      // ---- part 4, item 1.4.2: sectors and characteristics of minor lights ----
      { id: 'buoyage-29', q: 'What does the white sector of a Norwegian sector light show?', options: ['The fairway for the intended traffic, although shoals may still lie inside it', 'A prohibited area', 'Guaranteed deep water all the way to the light', 'An anchorage'], answer: 0, explanation: 'The white sector marks navigable water for the vessels expected there, but shoals can occur inside it, so read it with the chart. Red and green sectors mark foul water (F62, F63).', difficulty: 1, part: 4, p4: '1.4.2', tags: ['sector'] },
      { id: 'buoyage-30', q: 'You are steering towards a sector light in its white sector when it turns red. What has happened and what do you do?', options: ['You have drifted to starboard: alter course to port', 'You have drifted to port: alter course to starboard', 'The light has failed: continue on the same course', 'You are exactly on the fairway line: hold your course'], answer: 1, explanation: 'Heading for the light, red lies on your port side of the white sector. Seeing red means you have strayed to port, so turn to starboard until it is white (F64, F65).', difficulty: 2, part: 4, p4: '1.4.2', tags: ['sector'] },
      { id: 'buoyage-31', q: 'Heading towards a minor light, you see green. Which way do you alter course?', options: ['To starboard', 'No alteration: green means go', 'To port', 'Reverse course; green means the fairway is closed'], answer: 2, explanation: 'Green lies on the starboard side of the white sector when you head for the light, so green means you are too far to starboard: alter to port (F65, S6).', difficulty: 2, part: 4, p4: '1.4.2', tags: ['sector'] },
      { id: 'buoyage-32', q: 'The boat in the picture is heading towards the sector light. What does it see, and what should it do?', illustration: () => sectorScene('green'), options: ['Green: it is too far to starboard and should turn to port', 'Green: it is too far to port and should turn to starboard', 'Red: it is too far to port and should turn to starboard', 'White: it is in the fairway and should hold its course'], answer: 0, explanation: 'The boat lies in the green sector on the starboard side of the white fairway sector. Green means too far to starboard: turn to port until the light shows white (F64, F65).', difficulty: 2, part: 4, p4: '1.4.2', tags: ['sector', 'picture'] },
      { id: 'buoyage-33', q: 'The boat in the picture is heading towards the sector light. Which colour does it see, and what should it do?', illustration: () => sectorScene('red'), options: ['Green: turn to port', 'White: hold course', 'Red: it is too far to port and should turn to starboard', 'Red: it is too far to starboard and should turn to port'], answer: 2, explanation: 'The boat lies in the red sector, on the port side of the white fairway. Red means it has strayed to port: alter course to starboard (F64, F65).', difficulty: 2, part: 4, p4: '1.4.2', tags: ['sector', 'picture'] },
      { id: 'buoyage-34', q: 'You are running away from a sector light, keeping it astern in its white sector, when it turns red. Which way do you turn?', options: ['To starboard, as when heading towards the light', 'To port: with the light astern the colours are mirrored and red lies on your starboard side', 'Stop; a red sector astern means you must anchor', 'No change; sectors only apply when approaching'], answer: 1, explanation: 'Seen astern, the picture is mirrored: red lies on your starboard side, so red means you have drifted to starboard and must turn to port (F66, S7).', difficulty: 3, part: 4, p4: '1.4.2', tags: ['sector'] },
      { id: 'buoyage-35', q: 'How are the limits of a light sector given on the chart and in the list of lights?', options: ['As magnetic bearings from the light', 'As relative bearings from your bow', 'As true bearings from the sea towards the light, 0 to 360 clockwise', 'As true bearings from the light towards the sea'], answer: 2, explanation: 'Sector limits are true bearings from seaward, as seen by the mariner looking towards the light (F70).', difficulty: 3, part: 4, p4: '1.4.2', tags: ['sector'] },
      { id: 'buoyage-36', q: 'What does the character "Oc" mean on a chart?', options: ['Occulting: the light is on longer than it is off', 'Occasional: the light is only lit on request', 'Oscillating: the light moves', 'Off-centre: the light stands beside the fairway'], answer: 0, explanation: 'Oc = occulting, total light longer than total darkness: a steady light briefly switched off. Fl is the opposite, Iso is equal (F90).', difficulty: 1, part: 4, p4: '1.4.2', tags: ['character'] },
      { id: 'buoyage-37', q: 'What does "Iso" mean?', options: ['Isolated danger light', 'An intensified sector', 'Interrupted quick flashing', 'Light and dark periods of equal length'], answer: 3, explanation: 'Iso = isophase: light and dark of equal duration. It is one of the safe water rhythms (F91).', difficulty: 1, part: 4, p4: '1.4.2', tags: ['character'] },
      { id: 'buoyage-38', q: 'What does the chart description "Fl(3) WRG 15s 21m 15-11M" mean?', options: ['Fixed light in three colours, 15 m high, visible 21 M', 'Group flashing 3 every 15 s, white/red/green sectors, 21 m above mean high water, nominal range white 15 M, green 11 M, red between', 'Three lights 15 m apart, each 21 m high', 'Flashing every 3 s, 15 flashes a minute, range 21 M'], answer: 1, explanation: 'Fl(3) = three flashes in a group; WRG = sector colours; 15s = period; 21m = elevation above mean high water; 15-11M = nominal range white 15, green 11, red between (F98).', difficulty: 2, part: 4, p4: '1.4.2', tags: ['character', 'description'] },
      { id: 'buoyage-39', q: 'In "Oc WRG 6s 12m 9-6M", what does "9-6M" mean?', options: ['The light is visible from 9 to 6 o\'clock', 'The sector is 9 to 6 degrees wide', 'Nominal range white 9 M, green 6 M, red between 9 and 6 M', 'The light stands 9 to 6 m above the water'], answer: 2, explanation: 'The range figure gives nominal range in nautical miles: white 9 M, green 6 M, red between. 12m is the elevation above mean high water and 6s the period (F97, S5).', difficulty: 2, part: 4, p4: '1.4.2', tags: ['character', 'description'] },
      { id: 'buoyage-40', q: 'How long is a long flash (LFl)?', options: ['0.5 s', '1 s', '2 s or longer', 'At least 10 s'], answer: 2, explanation: 'A long flash lasts 2 s or more. It appears after the six flashes of a south cardinal and alone as "LFl 10s" on safe water marks (F93).', difficulty: 1, part: 4, p4: '1.4.2', tags: ['character'] },
      { id: 'buoyage-41', q: 'Which character is shown on this timeline?', illustration: () => S.lightRhythm('Oc 6s', { color: 'W' }), options: ['Fl 6s: flashing', 'Iso 6s: isophase', 'Oc 6s: occulting', 'F: fixed'], answer: 2, explanation: 'The light is on for most of the period and goes dark briefly: occulting, Oc 6s. A flashing light would be dark most of the time; isophase would be half and half (F90).', difficulty: 2, part: 4, p4: '1.4.2', tags: ['character', 'picture'] },
      { id: 'buoyage-42', q: 'Which character is shown on this timeline?', illustration: () => S.lightRhythm('Iso 4s', { color: 'W' }), options: ['Oc 4s', 'Fl 4s', 'Q', 'Iso 4s'], answer: 3, explanation: 'Light and dark are equal: isophase, Iso 4s. Oc would be mostly light, Fl mostly dark, Q a rapid series of flashes (F91).', difficulty: 1, part: 4, p4: '1.4.2', tags: ['character', 'picture'] },
      { id: 'buoyage-43', q: 'What does "Q" mean in a light character?', options: ['Quick flashing, 50 to 79 flashes a minute (usually 50 or 60)', 'Quarter-hour: the light flashes every 15 minutes', 'A quiet (unlit) sector', 'Very quick flashing, 100 or 120 a minute'], answer: 0, explanation: 'Q = quick, 50-79 flashes per minute, usually 50 or 60. VQ = very quick, 80-159 (usually 100 or 120); UQ = ultra quick, 160 or more (F29, F94).', difficulty: 2, part: 4, p4: '1.4.2', tags: ['character'] },
      { id: 'buoyage-44', q: 'What does the elevation "21m" in a light description refer to?', options: ['The height of the light above mean high water', 'The depth of water at the light', 'The height of the light above chart datum', 'The height of the tower above the ground'], answer: 0, explanation: 'Light elevations are given in metres above mean high water. Bridge and overhead cable clearances, by contrast, are referred to highest astronomical tide (F97, F88).', difficulty: 2, part: 4, p4: '1.4.2', tags: ['character', 'description'] },
      { id: 'buoyage-45', q: 'Which statement about the range printed in a light description is correct?', options: ['It is the distance at which you will always see the light', 'It is the nominal range, valid in a visibility of 10 nautical miles; fog and snow reduce it', 'It is measured in kilometres', 'It is the width of the white sector'], answer: 1, explanation: 'Nominal range assumes a meteorological visibility of 10 M; atmospheric conditions reduce the actual range, and the list of lights computes geographical range for a 5 m eye height (F99).', difficulty: 3, part: 4, p4: '1.4.2', tags: ['character', 'range'] },
      { id: 'buoyage-46', q: 'Between the red and green sectors of a light, and at every sector boundary, what should you expect?', options: ['A sharp, exact change of colour at the charted bearing', 'A small transition angle, typically about 2 degrees, where the colour is uncertain; between red and green the light may look white', 'A dark gap where the light is switched off', 'A flashing warning light'], answer: 1, explanation: 'Sector boundaries have a transition of about 2 degrees or less, and between red and green there is a narrow band that looks white. Wet or frosted glass can shift boundaries further (F71, F72).', difficulty: 3, part: 4, p4: '1.4.2', tags: ['sector'] },

      // ---- part 3: navigating by marks and lights (IALA A system, Norwegian practice) ----
      { id: 'buoyage-47', q: 'What is this mark, and how do you pass it?', illustration: () => qmark('isolated-danger', { light: true }), options: ['An isolated danger mark: water all around, pass either side at a safe distance', 'A west cardinal mark: pass west of it', 'A port-hand mark: keep it to port', 'A safe water mark: pass close on either side'], answer: 0, explanation: 'Black with a broad red band and two black spheres is the isolated danger mark. Navigable water lies all around, but the mark does not show the extent of the danger, so keep a safe distance and check the chart (F33, F34).', difficulty: 2, part: 3, tags: ['isolated-danger', 'picture'] },
      { id: 'buoyage-48', q: 'What does this mark mean?', illustration: () => qmark('safe-water', { light: true }), options: ['Danger directly beneath the mark', 'Preferred channel to port', 'Navigable water all around: a mid-channel or landfall mark', 'A fish farm'], answer: 2, explanation: 'Red and white vertical stripes with a red sphere topmark is the safe water mark. It marks no danger: mid-channel, fairway, landfall or the best passage under a bridge (F36, F37).', difficulty: 1, part: 3, tags: ['safe-water', 'picture'] },
      { id: 'buoyage-49', q: 'What is this buoy?', illustration: () => qmark('wreck', { light: true }), options: ['A special mark for a military area', 'A safe water mark', 'A north cardinal mark seen at night', 'An emergency wreck marking buoy: a new danger not yet on your chart'], answer: 3, explanation: 'Blue and yellow vertical stripes with an upright yellow cross and an alternating blue/yellow light is the emergency wreck marking buoy for new dangers. Keep well clear and check the Notices to Mariners (F45).', difficulty: 2, part: 3, tags: ['wreck', 'picture'] },
      { id: 'buoyage-50', q: 'Which white light rhythm is NOT a safe water rhythm?', options: ['Iso', 'Oc', 'Mo(A)', 'Fl(2)'], answer: 3, explanation: 'Safe water marks show Iso, Oc, one long flash every 10 s or Morse A. Fl(2) is the isolated danger light (F36, F33).', difficulty: 3, part: 3, tags: ['safe-water', 'light'] },
      { id: 'buoyage-51', q: 'A preferred channel buoy (red with a broad green band, light Fl(2+1) R) is described in the IALA system. Where will you meet it in Norway?', options: ['At every fjord junction', 'Only on the south coast', 'Nowhere: preferred channel buoys are not used in Norwegian waters', 'Only as a fixed beacon'], answer: 2, explanation: 'Norwegian charts and the pilot guide state that the preferred channel buoy is not used in Norwegian waters. Its Fl(2+1) rhythm is still the one rhythm forbidden for ordinary laterals (F19).', difficulty: 2, part: 3, tags: ['preferred-channel'] },
      { id: 'buoyage-52', q: 'What does a magenta arrow drawn in a fairway on a Norwegian chart show?', options: ['The tidal stream', 'A ferry route', 'A recommended speed limit', 'The direction of buoyage where it is not obvious'], answer: 3, explanation: 'The magenta arrow is the chart symbol for the direction of buoyage, printed where the direction is not obvious (F8).', difficulty: 1, part: 3, tags: ['direction', 'chart'] },
      { id: 'buoyage-53', q: 'Along the open Norwegian coast, which way does the direction of buoyage run?', options: ['Anticlockwise: from the Russian border south and east to Sweden', 'Clockwise round Norway: from the Swedish border west along the south coast, then north up the west coast', 'Always from north to south', 'There is no direction of buoyage along the coast, only in harbours'], answer: 1, explanation: 'The direction is fixed clockwise around the land mass: westwards along the south coast from the Swedish border, then northwards and north-eastwards to the Russian border; into every fjord it runs from seaward (F7, F7a).', difficulty: 3, part: 3, tags: ['direction'] },
      { id: 'buoyage-54', q: 'Why should you not use a floating buoy as a fixed reference point for your position?', options: ['Buoys are moved every week', 'A buoy swings on its mooring, may drift or capsize, and its charted position is only approximate', 'Buoys are not shown on Norwegian charts', 'Floating marks have no navigational meaning'], answer: 1, explanation: 'Floating marks swing inside a watch circle, can drift, capsize or be extinguished, and are checked only periodically, so their charted positions are approximate. Use bearings to fixed marks and the chart (F54, F55).', difficulty: 2, part: 3, tags: ['floating'] },
      { id: 'buoyage-55', q: 'Your searchlight shows a blue reflective band over a yellow band near the top of a spar buoy. What is the mark?', options: ['An emergency wreck buoy', 'A special mark', 'A north cardinal mark: blue stands for black', 'A safe water mark'], answer: 2, explanation: 'On Norwegian marks blue reflective tape stands for black paint. Blue over yellow is therefore black over yellow: the north cardinal (F31, F83).', difficulty: 3, part: 3, tags: ['reflector', 'cardinal'] },
      { id: 'buoyage-56', q: 'A high-speed-craft mark (HIB) shows the number 12 with a red reflector on its cone. Travelling in the main direction you should:', options: ['Keep it to starboard', 'Pass directly over it', 'Ignore it: it applies only to fast ferries', 'Keep it to port'], answer: 3, explanation: 'Even numbers with a red reflector mark the port side, odd numbers with a green reflector the starboard side, in the main direction; a white reflector means either side. The cone points towards the fairway (F81, F82, S11).', difficulty: 2, part: 3, tags: ['hib'] },
      { id: 'buoyage-57', q: 'Two leading daymarks appear exactly one above the other. What does that tell you?', options: ['You are on the leading line', 'You must turn 90 degrees', 'The channel is closed', 'You are too far to port'], answer: 0, explanation: 'A leading line consists of two marks or lights that are in line when you are on the correct track; the chart gives the bearing to steer (F75, F76).', difficulty: 1, part: 3, tags: ['leading-line'] },
      { id: 'buoyage-58', q: 'You are approaching on a leading line and see the marks as in the picture. Where are you and what do you do?', illustration: () => qlead(32), options: ['Left of the line: steer right', 'On the line: hold your course', 'Right of the line: steer left', 'Past the marks: turn round'], answer: 2, explanation: 'The rear (higher, apex-down) mark appears to the right of the front mark. The rear mark is displaced towards the side you are on, so you are right of the line and must steer left (S12).', difficulty: 3, part: 3, tags: ['leading-line', 'picture'] },
      { id: 'buoyage-59', q: 'On a bridge you see a circular sign with red and white vertical stripes. What does it mean?', options: ['The port side of the navigable span', 'A fish farm lies beyond the bridge', 'The bridge is closed to traffic', 'The best point of passage under the bridge'], answer: 3, explanation: 'The red/white striped circle (safe water colours) marks the best point of passage. A green triangle marks the starboard side of the span and a red square the port side (F86, F87).', difficulty: 1, part: 3, tags: ['bridge'] },
      { id: 'buoyage-60', q: 'What is "indirect lighting" of a skerry or breakwater head?', options: ['A flashing red lantern on top of it', 'A fixed yellow floodlight that lights up the object so that you see the object itself, not a lamp', 'A green sector covering it', 'A radar beacon'], answer: 1, explanation: 'Indirect lighting is a fixed yellow floodlight from a projector that illuminates the headland, skerry, pier or mark, giving daylight-like navigation and better distance judgement (F80).', difficulty: 2, part: 3, tags: ['floodlight'] },
    ],
  });
})();
